const token=location.hash.slice(1);const $=s=>document.querySelector(s);const fmt=x=>new Intl.DateTimeFormat('en-PH',{timeZone:'Asia/Manila',dateStyle:'full',timeStyle:'short'}).format(new Date(x));let appointment;async function call(data){const r=await fetch('/.netlify/functions/api',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,token})});const d=await r.json();if(!r.ok)throw Error(d.error);return d}function show(a){appointment=a;$('#info').textContent=`${a.reference} · ${a.service} · room ${a.room} · ${fmt(a.start)} · ₱${a.price.toLocaleString('en-PH')} · ${a.status} · receipt ${a.receiptStatus}`;$('#actions').hidden=a.status!=='booked'}async function load(){try{show((await call({action:'manage'})).appointment)}catch(e){$('#info').textContent=e.message}}$('#cancel').onclick=async()=>{if(!confirm('Cancel this appointment?'))return;try{const d=await call({action:'cancel'});show(d.appointment);$('#info').textContent+=d.late?' · Late cancellation flagged for staff review. The spa policy says late cancellations forfeit any downpayment; this site did not process payment.':'';$('#info').textContent+=d.emailSent?' · Confirmation email accepted for delivery.':' · Confirmation email was not sent.'}catch(e){$('#message').textContent=e.message}};$('#new-date').min=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());$('#new-date').onchange=async()=>{try{const d=await call({action:'manageAvailability',date:$('#new-date').value});$('#new-time').replaceChildren(new Option(d.slots.length?'Choose a time':'No available times',''));d.slots.forEach(s=>$('#new-time').add(new Option(s.label,s.value)))}catch(e){$('#message').textContent=e.message}};$('#move').onsubmit=async e=>{e.preventDefault();if(!confirm('Reschedule this appointment?'))return;try{const d=await call({action:'reschedule',date:$('#new-date').value,start:$('#new-time').value});show(d.appointment);$('#message').textContent=`Appointment rescheduled.${d.late?' This late change was flagged for staff review.':''} ${d.emailSent?'Confirmation email accepted for delivery.':'Confirmation email was not sent.'}`}catch(err){$('#message').textContent=err.message}};load();
